<template><v-app><main class="file-manager-fixture"><FileManager :active="active" :chat-id="owner" title="隔离文件选择检查" :directory="directory" @browse="browse" @preview="(path,chatId)=>actions.push({kind:'preview',path,chatId})" @notify="notices.push($event)" /></main></v-app></template>
<script setup lang="ts">
import {ref} from 'vue'
import FileManager from '../../src/components/FileManager.vue'
import type {NavoraApi} from '../../electron/preload'
import type {BrowserDownloadEntry} from '../../shared/types'
import type {NativeMenuResult,NativeUiApi} from '../../shared/native-ui'
const owner=ref('owner-a'),directory=ref('.'),active=ref(true),actions=ref<any[]>([]),notices=ref<string[]>([]),calls:any[]=[],menus:any[]=[],pending=new Map<string,(result:NativeMenuResult)=>void>()
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const roots:any[]=[{path:'folder',name:'folder',type:'dir'},{path:'a.md',name:'a.md',type:'file',size:10},{path:'b.png',name:'b.png',type:'file',size:20},{path:'done.zip',name:'done.zip',type:'file',size:30}]
const changes=new Set<(event:any)=>void>();let failList=false
let records:BrowserDownloadEntry[]=[{id:'complete',source:'browser',chatId:'owner-a',sessionId:'fixture',state:'completed',url:'https://fixture.invalid/done',filename:'done.zip',relPath:'done.zip',createdAt:1,updatedAt:1},{id:'pending',source:'browser',chatId:'owner-a',sessionId:'fixture',state:'started',url:'https://fixture.invalid/pending',filename:'pending.bin',relPath:'pending.bin',createdAt:1,updatedAt:1,canPause:true,canCancel:true}]
const nativeUi:NativeUiApi={capabilities:async()=>({menus:true,panels:false,pageInfo:false,distributionVersion:'fixture'}),popupMenu:input=>{menus.push(clone(input));return new Promise(resolve=>pending.set(input.requestId,resolve))},closeMenu:async id=>{const resolve=pending.get(id);pending.delete(id);resolve?.({supported:true,reason:'dismissed'})},updateMenu:async()=>false,onMenuOpened:()=>()=>{},onMenuControl:()=>()=>{},showPanel:async()=>({supported:false,id:'',session:''}),updatePanel:async()=>false,hidePanel:async()=>{},destroyPanel:async()=>{},onPanelEvent:()=>()=>{},showPageInfo:async()=>false}
window.navora={app:{platform:'win32'},nativeUi,workspace:{
  list:async(chatId:string,path:string)=>{calls.push({kind:'list',chatId,path});if(failList)return {ok:false,error:'fixture_missing_folder'};return {ok:true,entries:clone(chatId==='owner-b'?[{path:'other.md',name:'other.md',type:'file',size:5}]:path==='folder'?[{path:'folder/child.md',name:'child.md',type:'file',size:6}]:roots)}},
  resources:async(chatId:string)=>({ok:true,entries:clone(chatId==='owner-b'?[{path:'other.md',name:'other.md',size:5}]:[...roots.filter(entry=>entry.type==='file'),{path:'folder/child.md',name:'child.md',size:6}]),truncated:false,unavailable:0}),
  fileAction:async(chatId:string,path:string,action:string,options:unknown)=>{calls.push({kind:'file',chatId,path,action,options});return action==='inspect'?{ok:true,capabilities:{revision:'fixture:'+path,directory:path==='.'||path==='folder',openWith:true,copyContent:true}}:{ok:true}},
  reveal:async(chatId:string,path:string)=>{calls.push({kind:'reveal',chatId,path});return {ok:true}},onChanged:(callback:(event:any)=>void)=>{changes.add(callback);return()=>changes.delete(callback)},
},downloads:{list:async(chatId:string)=>clone(records.filter(item=>item.chatId===chatId)),onChanged:()=>()=>{},remove:async(id:string,chatId:string)=>{calls.push({kind:'remove-download',id,chatId});records=records.filter(item=>item.id!==id||item.chatId!==chatId);return {ok:true}},pause:async(id:string,chatId:string)=>{calls.push({kind:'pause',id,chatId});return {ok:true}}},agent:{onEvent:()=>()=>{},stop:async()=>({ok:true})}} as unknown as NavoraApi
function browse(path:string){actions.value.push({kind:'browse',path,chatId:owner.value});directory.value=path}
;(window as any).fileManagerFixture={get calls(){return calls},get actions(){return actions.value},get notices(){return notices.value},get menus(){return menus},get pending(){return [...pending.keys()]},get directory(){return directory.value},choose(selectedId?:string){const id=[...pending.keys()].at(-1),resolve=id&&pending.get(id);if(id)pending.delete(id);if(resolve)resolve({supported:true,selectedId,reason:selectedId?undefined:'dismissed'})},owner(value:string){owner.value=value;directory.value='.'},active(value:boolean){active.value=value},fail(value:boolean){failList=value},remove(path:string){const at=roots.findIndex(item=>item.path===path);if(at>=0)roots.splice(at,1);for(const callback of changes)callback({chatId:owner.value})}}
</script>
<style>html,body,#app{height:100%;margin:0;font-family:'Segoe UI','Microsoft YaHei UI',sans-serif}.v-application__wrap{height:100%;min-height:0!important}.file-manager-fixture{display:flex;height:100%;min-height:0;--navora-accent:#3f709b;--navora-ink:#283e50;--navora-muted:#72859a;--navora-stroke:#d7e1e8;--navora-surface:#fff}</style>
